function bindGlobalSearch(){const input=$('#adminGlobalSearch');const results=$('#adminGlobalSearchResults');if(!input||!results)return;let timer;input.addEventListener('input',()=>{clearTimeout(timer);const q=input.value.trim();if(q.length<2){results.hidden=true;return;}timer=setTimeout(async()=>{const [customers,bookings,tours,agents,tickets,payments]=await Promise.all([safeRequest(`/admin/customers?q=${encodeURIComponent(q)}&pageSize=5`),safeRequest(`/admin/bookings?q=${encodeURIComponent(q)}&pageSize=5`),safeRequest(`/admin/tours?q=${encodeURIComponent(q)}`),safeRequest(`/admin/travel-agents?q=${encodeURIComponent(q)}&pageSize=5`),safeRequest(`/admin/tickets?q=${encodeURIComponent(q)}`),safeRequest(`/admin/payments?q=${encodeURIComponent(q)}&pageSize=5`)]);const items=[];if(!isError(customers))items.push(...(customers.customers||[]).map(item=>({type:'Customer',label:displayName(item),detail:item.phone||item.email||item.id,route:`/admin/customers/${item.id}`,icon:'users'})));if(!isError(bookings))items.push(...(bookings.bookings||[]).map(item=>({type:'Booking',label:item.id.slice(0,12).toUpperCase(),detail:`${item.vertical} · ${displayName(item.customer)}`,route:`/admin/bookings/${item.id}`,icon:'briefcase'})));if(!isError(tours))items.push(...(tours.tours||[]).map(item=>({type:'Tour',label:item.title,detail:item.country,route:'/admin/tours',icon:'map'})));if(!isError(agents))items.push(...(agents.agents||[]).map(item=>({type:'Agent',label:item.fullName,detail:item.jobTitle||item.department,route:'/admin/travel-agents',icon:'users'})));if(!isError(tickets))items.push(...(tickets.tickets||[]).map(item=>({type:'Ticket',label:item.subject,detail:item.name,route:`/admin/support/${item.id}`,icon:'headset'})));if(!isError(payments))items.push(...(payments.payments||[]).map(item=>({type:'Payment',label:item.transactionRef||item.id.slice(0,12),detail:formatMoney(item.amount,item.currency),route:'/admin/payments',icon:'card'})));results.innerHTML=items.slice(0,15).map(item=>`<button class="global-search-result" data-global-route="${escapeAttr(item.route)}"><strong>${escapeHtml(item.type)} · ${escapeHtml(item.label)}</strong><small>${escapeHtml(item.detail||'')}</small></button>`).join('')||'<div class="empty-state" style="min-height:80px;padding:12px">No matching records.</div>';results.hidden=false;$$('[data-global-route]',results).forEach(button=>button.addEventListener('click',()=>{results.hidden=true;input.value='';navigate(button.dataset.globalRoute);}));},250);});document.addEventListener('click',event=>{if(!event.target.closest('.admin-global-search'))results.hidden=true;});}
function setMobileDrawerOpen(nextOpen, options = {}) {
  const sidebar = $('#adminSidebar'); const scrim = $('#adminScrim'); const open = Boolean(nextOpen) && isMobileView();
  if (open && !state.mobileDrawerOpen) { state.previousBodyOverflow = document.body.style.overflow; state.previousBodyPaddingRight = document.body.style.paddingRight; }
  state.mobileDrawerOpen = open;
  sidebar?.classList.toggle('open', open);
  sidebar?.setAttribute('aria-hidden', String(!open && isMobileView()));
  if (open) scrim?.removeAttribute('hidden'); else scrim?.setAttribute('hidden', '');
  $('#adminMenuToggle')?.setAttribute('aria-expanded', String(open));
  document.body.classList.toggle('admin-drawer-open', open);
  if (open) { const compensation = Math.max(0, window.innerWidth - document.documentElement.clientWidth); document.body.style.setProperty('--admin-scrollbar-compensation', `${compensation}px`); if (options.focus !== false) $('#sidebarClose')?.focus(); }
  else { document.body.style.removeProperty('--admin-scrollbar-compensation'); if (state.previousBodyOverflow !== null) { document.body.style.overflow = state.previousBodyOverflow; document.body.style.paddingRight = state.previousBodyPaddingRight || ''; state.previousBodyOverflow = null; state.previousBodyPaddingRight = null; } }
}
