  $('#adminOutlet').innerHTML = pageHeader('Operations', 'Hotel bookings', 'Review, confirm and manage hotel reservations, payments and refunds.', '') + `<section class="admin-card"><form class="filter-bar" id="hbFilterForm"><input class="filter-search" name="q" value="${escapeAttr(q)}" placeholder="Search booking ID, guest or hotel"/><select class="filter-select" name="status">${statuses.map(s => `<option value="${s}" ${s === status ? 'selected' : ''}>${s.replace(/_/g, ' ')}</option>`).join('')}</select><button class="admin-primary" type="submit">Search</button></form><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Hotel</th><th>Guest</th><th>Dates</th><th>Total</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
